package org.cbhs.bank.testers;

import org.cbhs.bank.model.Transaction;

/**
 * Run this class to check Transaction. Students do not edit this file.
 */
public class TransactionTester {
    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        Transaction t = new Transaction("deposit", 20.00, "Bake sale", "2026-08-13");
        check("type", t.getType().equals("deposit"));
        check("amount", Math.abs(t.getAmount() - 20.00) < 0.001);
        check("note", t.getNote().equals("Bake sale"));
        check("stamp", t.getStamp().equals("2026-08-13"));

        System.out.println();
        System.out.println("Passed: " + passed + "  Failed: " + failed);
        if (failed == 0) {
            System.out.println("TransactionTester: all tests passed.");
        } else {
            System.out.println("TransactionTester: some tests failed.");
        }
    }

    private static void check(String name, boolean ok) {
        if (ok) {
            passed++;
            System.out.println(name + " ... PASS");
        } else {
            failed++;
            System.out.println(name + " ... FAIL");
        }
    }
}
